<script setup lang="ts">
import { inject, onMounted, ref } from "vue"; import type { PluginCtx } from "../../shell/ctx"; import { errorText } from "./types";
const injectedCtx=inject<PluginCtx>("pluginCtx");if(injectedCtx===undefined)throw new Error("RoutesPanel requires PluginPaneHost");const ctx:PluginCtx=injectedCtx;const source=ref("{}");const error=ref("");const saved=ref(false);async function load(){source.value=JSON.stringify(await ctx.bus.request("chat:_:routing:get",{}),null,2)}async function save(){saved.value=false;try{const value=JSON.parse(source.value) as unknown;const result=await ctx.bus.request("chat:_:routing:put",value);source.value=JSON.stringify(result,null,2);error.value="";saved.value=true}catch(cause){error.value=errorText(cause)}}onMounted(()=>void load().catch(cause=>error.value=errorText(cause)));
</script>
<template><section class="d-flex flex-column h-100 p-2"><div class="d-flex align-items-center mb-1"><h6 class="m-0 me-auto">Routing policies</h6><span v-if="saved" class="small text-success me-2">Saved</span><button class="btn btn-sm btn-primary" title="Validate and save" @click="save"><i class="bi-check-lg" /></button></div><div v-if="error" class="small text-danger mb-1">{{error}}</div><textarea v-model="source" class="form-control form-control-sm font-monospace flex-grow-1" spellcheck="false" /></section></template>
